from pathlib import Path

p = Path('index.html')
s = p.read_text(encoding='utf-8')
marker = 'const [actionCenterRows, setActionCenterRows] = useState([]);'
if marker in s:
    print('already patched')
    raise SystemExit(0)

def req(old, new):
    global s
    if old not in s:
        raise SystemExit(f'Missing target snippet: {old[:120]!r}')
    s = s.replace(old, new, 1)

req(
'''    const [claims, setClaims] = useState([]);\n    const [claimsLoadError, setClaimsLoadError] = useState(null);\n''',
'''    const [claims, setClaims] = useState([]);\n    const [claimsLoadError, setClaimsLoadError] = useState(null);\n    const [actionCenterRows, setActionCenterRows] = useState([]);\n    const [actionCenterLoadError, setActionCenterLoadError] = useState(null);\n''')

req('''        if (!user) {\n            setClaims([]);\n            setLoading(false);\n''', '''        if (!user) {\n            setClaims([]);\n            setActionCenterRows([]);\n            setLoading(false);\n''')

req('''            const all = await SDLG_REPOSITORY.listClaims();\n            setClaims(all);\n            setClaimsLoadError(null);\n''', '''            const [all, actionRows] = await Promise.all([\n                SDLG_REPOSITORY.listClaims(),\n                runSupabaseRead(async () => {\n                    const result = await sdlgSupabase.from("claim_action_center_v").select("*");\n                    return result;\n                })\n            ]);\n            setClaims(all);\n            setClaimsLoadError(null);\n            if (actionRows?.error) throw actionRows.error;\n            setActionCenterRows(actionRows?.data || []);\n            setActionCenterLoadError(null);\n''')

req('''            setClaimsLoadError(e?.message || "Unknown error");\n            showToast("Gagal load data: " + (e?.message || "Unknown error"));\n''', '''            const msg = e?.message || "Unknown error";\n            setClaimsLoadError(msg);\n            setActionCenterLoadError(msg);\n            showToast("Gagal load data: " + msg);\n''')

req('''    else {\n        setClaims([]);\n        setLoading(false);\n    } }, [user, loadClaims]);\n''', '''    else {\n        setClaims([]);\n        setActionCenterRows([]);\n        setActionCenterLoadError(null);\n        setLoading(false);\n    } }, [user, loadClaims]);\n''')

anchor = '''                React.createElement("div", { style: { display: "grid", gridTemplateColumns: "minmax(0,1.35fr) minmax(260px,.65fr)", gap: 14, marginTop: 14, alignItems: "start" } },\n'''
block = '''                (() => {\n                    const active = claims.filter(c => !c.archived_at);\n                    const rows = actionCenterRows.length ? actionCenterRows : active.map(c => ({\n                        claim_id: c.claim_id,\n                        priority: "P2",\n                        action_required: false,\n                        next_action: "Review",\n                        readiness_status: null\n                    }));\n                    const counts = rows.reduce((a, r) => {\n                        const p = String(r.priority || "P2").toUpperCase();\n                        a[p] = (a[p] || 0) + 1;\n                        return a;\n                    }, {});\n                    const actionRequired = rows.filter(r => r.action_required === true);\n                    const p1Rows = rows.filter(r => String(r.priority || "").toUpperCase() === "P1");\n                    const p0Rows = rows.filter(r => String(r.priority || "").toUpperCase() === "P0");\n                    const topActions = Object.entries(actionRequired.reduce((a, r) => {\n                        const k = r.next_action || "Review";\n                        a[k] = (a[k] || 0) + 1;\n                        return a;\n                    }, {})).sort((a, b) => b[1] - a[1]).slice(0, 4);\n                    const openActionClaims = actionRequired\n                        .map(r => ({ row: r, claim: claims.find(c => c.claim_id === r.claim_id) }))\n                        .filter(x => x.claim)\n                        .sort((a, b) => {\n                            const rank = { P0: 0, P1: 1, P2: 2, NONE: 3 };\n                            return (rank[String(a.row.priority || "P2").toUpperCase()] ?? 9) - (rank[String(b.row.priority || "P2").toUpperCase()] ?? 9);\n                        })\n                        .slice(0, 5);\n                    const goToClaim = claimId => {\n                        setTab("list");\n                        setDetailId(claimId);\n                    };\n                    const actionCards = [\n                        { label: "P0 Critical", value: counts.P0 || 0, hint: "Data inti / blocking issue", priority: "P0" },\n                        { label: "P1 Action Required", value: counts.P1 || 0, hint: "Perlu tindakan Warranty Admin", priority: "P1" },\n                        { label: "P2 Monitoring", value: counts.P2 || 0, hint: "Belum perlu intervensi", priority: "P2" },\n                        { label: "Total Action", value: actionRequired.length, hint: "Semua claim yang butuh tindakan", priority: "ACTION" }\n                    ];\n                    return React.createElement("div", { style: { marginTop: 14 } },\n                        React.createElement("div", { className: "card card-pad", style: { border: "1px solid #dbeafe", background: "linear-gradient(135deg,#ffffff 0%,#f8fbff 100%)" } },\n                            React.createElement("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center", gap: 12, flexWrap: "wrap", marginBottom: 12 } },\n                                React.createElement("div", null,\n                                    React.createElement("div", { className: "section-title" }, "⚡ My Action Today"),\n                                    React.createElement("div", { className: "section-sub" }, "Prioritas operasional dari Action Center database.")),\n                                React.createElement("div", { style: { fontSize: 10, color: actionCenterLoadError ? "#dc2626" : "#64748b" } }, actionCenterLoadError ? "Action Center fallback" : "Live dari claim_action_center_v")),\n                            React.createElement("div", { style: { display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(160px,1fr))", gap: 10 } },\n                                actionCards.map(x => React.createElement("button", { key: x.label, onClick: () => {\n                                    if (x.priority === "P0" || x.priority === "P1") setTab("list");\n                                    else if (x.priority === "P2") setTab("list");\n                                }, style: { textAlign: "left", padding: "12px 13px", border: "1px solid #e2e8f0", background: "#fff", borderRadius: 10, cursor: "pointer" } },\n                                    React.createElement("div", { style: { display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 8 } },\n                                        React.createElement("b", { style: { fontSize: 22, color: x.value ? "#0f172a" : "#94a3b8" } }, x.value),\n                                        React.createElement("span", { style: { fontSize: 10, fontWeight: 800, color: x.value ? "#2563eb" : "#94a3b8" } }, x.value ? "ACTION" : "CLEAR")),\n                                    React.createElement("div", { style: { fontSize: 11, fontWeight: 700, color: "#334155", marginTop: 4 } }, x.label),\n                                    React.createElement("div", { style: { fontSize: 10, color: "#94a3b8", marginTop: 3, lineHeight: 1.4 } }, x.hint)))),\n                            topActions.length ? React.createElement("div", { style: { marginTop: 12, display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(220px,1fr))", gap: 8 } },\n                                topActions.map(([label, n]) => React.createElement("div", { key: label, style: { padding: "9px 10px", borderRadius: 8, background: "#f8fafc", border: "1px solid #e2e8f0" } },\n                                    React.createElement("div", { style: { fontSize: 10, color: "#64748b" } }, "Top action"),\n                                    React.createElement("div", { style: { fontSize: 12, fontWeight: 800, color: "#0f172a", marginTop: 2 } }, label),\n                                    React.createElement("div", { style: { fontSize: 11, color: "#2563eb", fontWeight: 800, marginTop: 2 } }, n, " claim")))) : null,\n                            openActionClaims.length ? React.createElement(\n                                "div",\n                                { style: { marginTop: 12 } },\n                                React.createElement("div", { style: { fontSize: 11, fontWeight: 800, color: "#334155", marginBottom: 7 } }, "Claim prioritas"),\n                                ...openActionClaims.map(({ row, claim }) => React.createElement("button", {\n                                    key: row.claim_id,\n                                    onClick: () => goToClaim(row.claim_id),\n                                    style: { width: "100%", display: "flex", alignItems: "center", gap: 10, padding: "9px 0", border: "none", borderBottom: "1px solid #f1f5f9", background: "transparent", cursor: "pointer", textAlign: "left" }\n                                },\n                                    React.createElement("span", { style: { minWidth: 34, fontSize: 9, fontWeight: 900, color: String(row.priority || "P2").toUpperCase() === "P0" ? "#dc2626" : String(row.priority || "P2").toUpperCase() === "P1" ? "#d97706" : "#2563eb" } }, String(row.priority || "P2").toUpperCase()),\n                                    React.createElement("span", { style: { flex: 1, minWidth: 0 } },\n                                        React.createElement("span", { style: { display: "block", fontFamily: "monospace", fontSize: 10, fontWeight: 800, color: "#0f172a" } }, claim.claim_id),\n                                        React.createElement("span", { style: { display: "block", fontSize: 10, color: "#64748b", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" } }, claim.model || "—", " · ", claim.customer || "—")),\n                                    React.createElement("span", { style: { fontSize: 10, color: "#475569", fontWeight: 700, maxWidth: 260, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" } }, row.next_action || "Review")\n                                ))\n                            ) : null,\n                            React.createElement("div", { style: { marginTop: 10, fontSize: 10, color: "#94a3b8" } }, p0Rows.length ? "Ada claim critical yang memerlukan perhatian segera." : p1Rows.length ? "P1 adalah backlog tindakan utama saat ini." : "Tidak ada claim P0/P1 yang memerlukan tindakan segera."))\n                    );\n                })(),\n'''
req(anchor, block + anchor)
p.write_text(s, encoding='utf-8')
print('patched', p.stat().st_size)
